export function srcsetFor(src) {
  if (!src) return undefined;
  const f = src.split('/').pop();
  return IMAGE_SRCSETS[f];
}

// Heroes render full viewport width; bodies render ~592px in the
// 2-col grid @1280 and full width (vw-40px) below the 640px breakpoint.
export const HERO_SIZES = "100vw";
export const BODY_SIZES = "(max-width: 640px) 100vw, 600px";
